import '../l10n/app_localizations.dart';
import '../models/car_model.dart';
import '../models/maintenance_reminder.dart';
import 'localized_vehicle_text.dart';

/// The title to show (and to use in the notification) for [reminder].
///
/// Registration / insurance / inspection reminders are generated by the app from
/// the car's document dates (ids `<carId>_registration|_insurance|_inspection`).
/// Their stored title was built with the language active when the car was saved,
/// so a car saved in English kept "Registration expiry - ..." in the Arabic UI.
/// For these generated reminders the title is rebuilt from l10n in the current
/// language; reminders typed by the user are returned unchanged.
String reminderDisplayTitle({
  required AppLocalizations l10n,
  required String languageCode,
  required MaintenanceReminder reminder,
  required List<CarModel> cars,
}) {
  final id = reminder.id;
  String? type;
  if (id.endsWith('_registration')) {
    type = l10n.registrationExpiry;
  } else if (id.endsWith('_insurance')) {
    type = l10n.insuranceExpiry;
  } else if (id.endsWith('_inspection')) {
    type = l10n.inspectionExpiry;
  }
  if (type == null) return reminder.title;

  final carId = id.substring(0, id.lastIndexOf('_'));
  for (final car in cars) {
    if (car.id == carId) {
      return '$type - ${l10n.carBrand(car.brand)} ${l10n.localizedCarModel(car.model, languageCode)} - ${car.year}';
    }
  }
  return reminder.title;
}
